    append(loyalty_1_delta_rows, p1);
    append(loyalty_1_remaining_rows, p2);
    append(loyalty_1_valid_until_rows, p3);
    append(loyalty_1_needs_review_rows, p4);
}
function integer count() {
    loyalty_1_point_action_rows = [];
    loyalty_1_delta_rows = [];
    loyalty_1_remaining_rows = [];
    loyalty_1_valid_until_rows = [];
    loyalty_1_needs_review_rows = [];
    loyalty_1_source = $in.0.activity_id;
    /* Branch census:
       1. unknown member -> 1 rows
       2. cancelled activity -> 0 rows
       3. invalid movement -> 1 rows
       4. expired balance -> 2 rows
       5. insufficient points -> 1 rows
       6. reviewed bonus -> 3 rows
       7. simultaneous earn and spend -> 3 rows
       8. positive earning -> 1 rows
